window.MONSTER_CHUNK_108 = [{"name":"Vegepygmy Commoner","cr":0.5,"xp":200,"alignment":"N","size":"Small","type":"plant","subtypes":["fungus"],"init":2,"senses":[{"type":"low-light vision"}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":4,"hd":"1d8","hdvalue":1,"fort":2,"ref":2,"will":0,"dr":"5/bludgeoning or slashing","immunities":["electricity","plant traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +1 (1d3) or spear +1 (1d6/x3)","ranged":"spear +3 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":14,"constitution":11,"intelligence":6,"wisdom":11,"charisma":10,"baseatk":0,"cmb":-1,"cmd":11,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":10,"special":"+18 in forested or swampy areas"}],"environments":["any underground"],"organizations":["(Commoner and Worker) gang (2-5)","work force (4-7)"],"treasure":"standard","description_visual":"This creature resembles a humanoid with green vegetable-like skin and razor-sharp claws. Its head sports two large yellow eyes, a wide mouth, inset nose, and a topknot of dark brown leaves. Leafy tendrils protrude from its shoulders, midsection, arms, and legs.","group":"Vegepygmy","source":"Tome of Horrors Complete (3pp)","description":"When a living creature is slain by russet mold (see that entry), it rises as a vegepygmy commoner. Vegepygmies are low-intelligence plants that make their home deep in the forests or underground away from most settled areas. They are hunters and scavengers, and carnivorous, preying on living creatures weaker than themselves. A vegepygmy ranges from two ft. to four and a half ft. tall. Though they don't seem to have ears, it is well known that vegepygmies can hear. Vegepygmies don't speak, but communicate with others of their kind by thumping their chest or rapping their spears on rocks, earth, or some other solid surface. It isn't known if or how they communicate with other creatures. Vegepygmies attack with claws or weapons, usually either a longspear or club. They prefer to ambush opponents, using their coloration to blend with their natural surroundings.","ecology":"","habitat_society":"","credit":"The Vegepygmy originally appeared in the First Edition module S3 Expedition to the Barrier Peaks (© TSR/Wizards of the Coast, 1980) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission.","gear":"spear"},{"name":"Vilstrak","cr":0.5,"xp":200,"alignment":"NE","size":"Medium","type":"aberration","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+8 natural","hp":5,"hd":"1d8+1","hdvalue":1,"fort":1,"ref":0,"will":2,"speed":[{"type":"land","speed":30}],"melee":"2 slams +2 (1d4+2)","space":"5 ft.","reach":"5 ft.","strength":15,"dexterity":11,"constitution":13,"intelligence":6,"wisdom":10,"charisma":8,"baseatk":0,"cmb":2,"cmd":12,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":4,"special":"+12 in rocky surroundings"}],"languages":["Terran"],"sq":[{"type":"merge with earth"}],"environments":["any underground"],"organizations":["gang (2-5)","band (6-20)"],"treasure":"standard","description_visual":"This creature is a bipedal man-sized semi-humanoid seemingly carved of stone. It has an insect-like head, long, large arms, and thick, trunklike legs that end in hoof-like ft.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Merge with Earth","kind":"Su","details":"A vilstrak can merge with earth or stone at will as a standard action. This ability is similar to a meld with stone spell (CL 12th), except that a vilstrak can see what goes on outside and it can remain merged as long as it desires."}],"description":"Vilstraks (or tunnel thugs) dwell underground, away from the surface world. Though they have no allergy or reaction to sunlight, they disdain its existence, preferring the cold, damp blackness of their underground world. A vilstrak's lair is a \"pocket\" formed deep inside the earth. These pockets have no exits or entrances and are only reachable by those who can pass through stone or earth.\n\nA typical vilstrak stands six ft. tall and weighs about 200 pounds. Its arms have an extra joint between the elbow and wrist, and its arms end in large, powerful fists of stone. Vilstraks are gray or brown.\n\nVilstraks are peaceful creatures that avoid combat if possible. They do take great joy and pride in robbing those that invade their territory.\n\nA favored tactic of the vilstrak is to hide inside the wall of a dungeon corridor and spring out when prey passes nearby.","ecology":"","habitat_society":"","credit":"The Vilstrak originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Vulchling","cr":0.5,"xp":200,"alignment":"CE","size":"Medium","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":11,"ac_mods":"+2 Dex, +1 dodge, +1 natural","hp":5,"hd":"1d10","hdvalue":1,"fort":2,"ref":4,"will":0,"speed":[{"type":"land","speed":20},{"type":"fly","speed":10,"maneuverability":"average"}],"melee":"bite +3 (1d6), 2 claws +3 (1d4)","space":"5 ft.","reach":"5 ft.","strength":10,"dexterity":14,"constitution":11,"intelligence":7,"wisdom":11,"charisma":10,"baseatk":1,"cmb":1,"cmd":14,"feats":[{"feat":"Dodge","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Perception","value":0,"special":"+8 in daylight"},{"skill":"Stealth","value":6}],"languages":["Auran"],"environments":["any underground"],"organizations":["solitary","flock (2-16)"],"treasure":"standard","description_visual":"This creature looks like a man-sized vulture with inky black feathers, a gray beak, and dark brownish-black talons.","source":"Tome of Horrors Complete (3pp)","description":"Vulchlings are a malevolent race of avian creatures akin to the vulture.\n\nTheir faces, though bird-like, seem to have an almost human quality to them. Vulchlings are not only scavengers but also predators, feeding on living prey as well as carrion. Vulchlings can occasionally be found in the company of harpies or vrocks, but most of their time is spent in their lairs-usually large nests found deep within the earth.\n\nVulchlings prefer to attack from secret or ambush by lying in wait for their prey and then swooping in to attack with their razor-sharp talons and beak. Slain opponents are carried back to the vulchlings' lair and fed to the young vulchlings.","ecology":"","habitat_society":"","credit":"The Vulchling originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Xothotak","cr":0.5,"xp":200,"race":"Xothotak","classes":[{"class":"warrior","level":1}],"alignment":"N","size":"Medium","type":"humanoid","subtypes":["xothotak"],"init":1,"senses":[{"type":"low-light vision"}],"ac":12,"ac_touch":11,"ac_flat_footed":11,"ac_mods":"+1 Dex, +1 natural","hp":7,"hd":"1d10+2 (+1)","hdvalue":1,"fort":4,"ref":1,"will":0,"speed":[{"type":"land","speed":30}],"melee":"spear +3 (1d8+3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":13,"constitution":14,"intelligence":8,"wisdom":11,"charisma":9,"baseatk":1,"cmb":3,"cmd":14,"feats":[{"feat":"Alertness"}],"skills":[{"skill":"Perception","value":2},{"skill":"Sense Motive","value":2},{"skill":"Stealth","value":9,"special":"+13 when not moving"}],"languages":["Xothotak"],"environments":["warm forests","warm jungles"],"organizations":["solitary","gang (2-4)","hunting band (5-12 plus 1 leader of 3rd-6th level)","tribe (30-100 plus 150% noncombatants, 1 tribal warrior of 3rd level per 10 adults, 1-3 shamans of 3rd-6th level, 1 veteran warrior of 5th level per 20 adults, plus 1 leader of 8th level)"],"treasure":"standard (leather armor, spear)","description_visual":"This primitive humanoid clutches a spear in its hand. Its skin tone seems to change colors shifting to match its surroundings.","source":"Tome of Horrors 4 (3pp)","description":"The xothotak are a savage race of cannibals that make their homes deep in the jungles and forests, far away from civilized lands. Bands of xothotak conduct raids into civilized settlements when food, women, and sacrifices are scarce. Captured men, women, and children are beaten, bound, and forced into slavery for a period of time, before being sacrificed to one of the xothotak's dark gods or served as a meal at a xothotak banquet. Xothotak bands also conduct raids on other xothotak tribes, often traveling many miles to attack a tribe. Many tribes form loose alliances with each other, trading food and women when needed or in abundance; but even that doesn't protect one from the other when food is scarce or when the gods demand a sacrifice. Tribes also form alliances when the son or daughter of the tribal leader marries into another tribe. Such an alliance is considered sacred, and breaking it is believed to bring the wrath of the gods down on one that betrays such an allegiance.\n\nXothotak culture and civilization varies from tribe to tribe, with some living in mud or wooden huts hidden among the trees, and larger more advanced tribes building clearing great expanses of trees and undergrowth to build elaborate cities of stone.\n\nSmaller xothotak tribes dwell in crude huts fashioned of timber and other resources found in the jungles or forests. Such huts are usually built in a circular formation around a great tree or sacred spring. One hut, larger than the others, houses the tribal leader and his family. A sacred hut where the xothotak shaman lives often adjoins or sits nearby. This temple is considered sacred by all in the tribe. To desecrate it is to bring death upon oneself.\n\nLarger and more advanced xothotak tribes live in what could only be called small cities or towns. Such locations tend to integrate the surrounding land and natural resources into their construction, such as houses or temples built into the sides of rock formations. These cities seem to have a haphazard and scattered design about them, the only organized and planned area being the plazas, temples, and shrines usually found at the center of a xothotak city. Large open plazas are where the xothotak gather to communicate, trade, buy, worship, or sell whatever they can find and whatever they can afford. These plazas are surrounded by temples, great pyramids dedicated to a plethora of gods, shrines, and the palace of the xothotak leader. As one leaves the plaza's center, smaller temples and shrines, as well as noble houses can be found encircling those closest to the plaza. Poor and common houses are found at the outer band of such a layout.\n\nXothotaks standing still are extremely hard to detect as they can alter their skin coloration to blend with their surroundings just as a chameleon can. Thus, these humanoids prefer to attack from ambush whenever possible. Traps are sometimes set to injure, maim or capture their prey. Xothotak warriors rely on primitive weapons in battle, and rarely if ever wear armor. Xothotak shamans rarely enter battle, preferring to use their magic to aid those going into battle or tend to those returning from battle. Xothotaks fear arcane magic and don't associate with arcane spellcasters (except to sacrifice such a caster to one of their gods or to serve the caster as food at an elaborate xothotak feast).\n\nXothotaks tend to be warriors, fighters, or barbarians. Xothotaks never take levels in any arcane spellcasting class. Xothotak shamans are always clerics.","as_character":[{"description":"Xothotaks are defined by their class levels-they don't possess racial Hit Dice. All xothotaks have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Strength, +2 Dexterity, +2 Constitution, -2 Intelligence, -2 Charisma."},{"type":"Sneaky","value":"Xothotaks have a +4 racial bonus on Stealth checks. This bonus increases to +8 when the xothotak isn't moving. Stealth is always a class skill for a xothotak."},{"type":"Languages","value":"All xothotaks begin play speaking their own native language. Xothotaks with high Intelligence scores can choose any of the following bonus languages: Common, Goblinoid, Sylvan, and Orc.\n\nBelow is a listing of some of the Xothotak gods and goddesses:\n\nItlatl - The Creator\n\nXolaca - The Lord of the Sky\n\nQuentzalma - Lord of the Underworld\n\nAtzin - God of Rain and Storms\n\nOchactl - The Lord of Thunder and Lightning\n\nAhuaxpin - God of the Hunt\n\nMalacihe - Goddess of Marriage and Sexuality\n\nCahitli - Goddess of Midwives and Fertility."}]}],"ecology":"","habitat_society":""},{"name":"Abyssal Larva","cr":1,"xp":400,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","evil","extraplanar"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 natural","hp":8,"hd":"1d10+3","hdvalue":1,"fort":2,"ref":2,"will":0,"immunities":["mind-affecting effects"],"resists":[{"type":"acid","value":5},{"type":"cold","value":5},{"type":"fire","value":5}],"speed":[{"type":"land","speed":20}],"melee":"bite +1 (1d4 plus 1d4 acid)","ranged":"maggot spray +1 (sickened)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid"},{"type":"maggot spray"}],"strength":10,"dexterity":10,"constitution":11,"intelligence":3,"wisdom":10,"charisma":7,"baseatk":1,"cmb":1,"cmd":11,"cmd_special":"can't be tripped","feats":[{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":4},{"skill":"Stealth","value":4}],"sq":[{"type":"tortured mind"}],"environments":["any Abyss"],"organizations":["mob (4-7)","brood (8-17)"],"treasure":"none","description_visual":"This creature looks like a puffy and bloated human-sized whitish-yellow maggot with purplish veins pulsating under its fleshy form. A vaguely humanoid head sits atop its body and its facial features are twisted and distraught as if the creature was in a constant state of pain. A pair of large, downward-curving horns juts from its head, just above its sunken eyes. Its mouth is lined with filthy and sharpened fangs.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":": Abyssal larvae use digestive juices to break down their foods. This acid often remains in their mouths and is transferred to a victim bitten by a larva. Any melee bite attack deals acid damage."},{"type":"Maggot Spray","kind":"Ex","details":": Once per day, an abyssal larva can regurgitate and fire a stream of maggots at a single opponent within 10 ft. This requires the abyssal larva to succeed on a ranged touch attack. If the attack succeeds, the opponent is sickened for 1d2 rounds. A successful DC 10 Reflex save reduces the sickened condition to 1 round. The save DC is Strength-based."},{"type":"Tortured Mind","kind":"Ex","details":": The mind of an abyssal larva is a warped and tangled mass of chaos. As a result, abyssal larvae are immune to all mind-affecting effects (charms, compulsions, phantasms, patterns, and morale effects). A creature attempting to contact an abyssal larva with a mind-affecting spell or effect (including psionics) must succeed on a DC 14 Will save or be affected as by a confusion spell for 1 minute. The save DC is Constitution-based and includes a +4 racial bonus."}],"description":"Abyssal larvae are believed to be the final form of an evil soul deemed too weak to become a demon and too weak to become the servant of a demon. Another theory suggests that the larvae are the imprisoned forms of slain demon princes and lords. Whatever their true origin, abyssal larvae are plentiful throughout the Abyssal planes, and are some of the most disgusting and loathsome creatures encountered.\n\nThese creatures feed on anything they can consume, be it rotting carcasses, freshly slain creatures, and even waste. Consumables are first liquefied through a process requiring the abyssal larva to regurgitate stomach acids onto its meal. As the food breaks down, the larva slurps it up and consumes it.\n\nWhile loathed by the more civilized, some demons, such as dretches and babaus, savor the juicy flesh of these creatures and often engage in hunting expeditions across the Abyss, killing and devouring as many of these creatures as they can find.\n\nActing as if almost mindless, abyssal larvae attack any living creature they encounter. They have no real tactics other than swarming a foe and biting relentlessly. These creatures fight until destroyed.\n\nAn abyssal larva's natural weapons, as well as any weapon it wields, is treated as chaotic-aligned and evil-aligned for the purpose of overcoming damage reduction.","ecology":"","habitat_society":""},{"name":"Amber Ooze","cr":1,"xp":400,"alignment":"N","size":"Diminutive","type":"ooze","init":0,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":14,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 size, +0 natural","hp":6,"hd":"1d8+2","hdvalue":1,"fort":2,"ref":0,"will":-5,"immunities":["ooze traits"],"speed":[{"type":"land","speed":10}],"space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"ability drain"},{"type":"infuse"},{"type":"weaken will"}],"strength":4,"dexterity":10,"constitution":14,"wisdom":1,"charisma":1,"baseatk":0,"cmb":-4,"cmd":3,"cmd_special":"can't be tripped","environments":["any temperate land","any warm land"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature resembles a small pool of liquid the color and consistency of mead.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Ability Drain","kind":"Ex","details":"If not purged form the host body, the acids and protoplasm of an amber ooze begin damaging its host's body and mind. After 1 week, the host takes 1 point each of Intelligence, Wisdom, and Charisma drain per day. When one of the three abilities reaches 0, the host dies."},{"type":"Infuse","kind":"Ex","details":"A victim that has ingested an amber ooze must succeed on a DC 13 Fortitude save or the amber ooze infuses itself into his body. The ooze merges with flesh and bone, and can only be removed by a remove disease spell. The save DC is Constitution-based. A detect magic (or similar magic) cast on the host reveals the amber ooze. If the victim succeeds on the Fortitude save, the amber ooze takes 1 point of acid damage per round from the host's digestive juices. Once it begins to take damage, the ooze retreats from the host's body through its mouth."},{"type":"Weaken Will","kind":"Su","details":"An amber ooze that has infused itself into a host weakens the will of its victim. As long as the amber ooze remains in the host, he takes a -4 penalty on Will saves to resist mind-influencing spells and effects (such as charm person and suggestion.)"}],"description":"Amber oozes were created by an evil wizard as a means of gaining control over the elders of a powerful city. He bred many of the creatures in secret and sealed them into kegs of ale, then hired merchants to distribute this ale throughout the city. The wizard was ultimately slain and the city saved by a band of heroic adventurers. Unknown to the adventurers, the merchants had wanted to line their own pockets without the knowledge of their employer. Unaware of the plot they sold some of the kegs of ale in illegal markets. Now, many of the kegs containing amber oozes have been shipped to other cities and the creatures are spreading. When an amber ooze divides, one of the new creatures seeps out of the keg to find its own lair. Stacked in rows with other kegs of uncontaminated ale, amber oozes can quickly take over a store room or pantry. An amber ooze is approximately 1 foot in diameter, and is a dark amber color. The designs of the mad mage even provided the amber ooze with the scent of mead or heady ale. Amber oozes can lay in a state of hibernation for years, coming out of it only to replicate - a process they undergo once every few months - or when they are alerted by movement of the keg. When a keg containing an amber ooze is tapped, the creature makes its way to the opening. Within the drawing of a few drinks, the amber ooze squeezes out of the tap and into the mug. As soon as the victim drinks, the ooze forces itself down the victim's throat and into its belly.","ecology":"","habitat_society":""},{"name":"Atomie","cr":1,"xp":400,"alignment":"CN","size":"Tiny","type":"fey","init":7,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 size, +0 natural","hp":10,"hd":"3d6","hdvalue":3,"fort":1,"ref":6,"will":4,"dr":"5/cold iron","sr":12,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"short sword +6 (1d3-3)","ranged":"light crossbow +6 (1d4)","space":"2-1/2 ft.","reach":"0 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":3,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"blink"},{"spell":"entangle"},{"spell":"invisibility","details":"self only"},{"spell":"pass without trace"},{"spell":"speak with animals"}]}],"strength":5,"dexterity":17,"constitution":11,"intelligence":12,"wisdom":13,"charisma":14,"baseatk":1,"cmb":2,"cmd":9,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Bluff","value":8},{"skill":"Craft (any)","value":7},{"skill":"Escape Artist","value":9},{"skill":"Fly","value":11},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":7},{"skill":"Perform (dance)","value":8},{"skill":"Stealth","value":11,"special":"+15 in forests"}],"languages":["Common","Sylvan"],"environments":["temperate forests"],"organizations":["gang (2-4)","band (6-11 plus 2-4 grigs)","tribe (20-80)"],"treasure":"standard","description_visual":"This creature resembles a small elf with narrow, pointed ears, long legs and arms, and lightly colored hair and eyes. Its skin has a light green color to it.","source":"Tome of Horrors Complete (3pp)","description":"Atomies are among the smallest of the fey. They dwell in arboreal regions, with a single atomie family staking their claim to a single tree. The atomies are nocturnal, leaving the safety of their treetop abodes under cover of darkness to dance and play among the underbrush.\n\nAn atomie is a 1-foot tall creature related to pixies and other sprites. Atomies are attractive, especially when compared to other sprites. Atomie clothing is almost always magical, made to change color with the seasons to help hide the wearer during all times of the year.","ecology":"","habitat_society":"","credit":"The Atomie originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Barbegazi","cr":1,"xp":400,"alignment":"NE","size":"Small","type":"humanoid","subtypes":["cold","gnome"],"init":1,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 Dex, +2 natural, +1 size","hp":11,"hd":"2d8+2","hdvalue":2,"fort":4,"ref":1,"will":0,"immunities":["cold"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":20}],"melee":"short sword +3 (1d4) or dagger +3 (1d3)","ranged":"dagger +3 (1d3)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"chill metal"},{"spell":"icicle blast","details":"as burning hands, but deals cold damage"}]}],"strength":10,"dexterity":13,"constitution":13,"intelligence":11,"wisdom":11,"charisma":8,"baseatk":1,"cmb":0,"cmd":11,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Craft (trapmaking)","value":7},{"skill":"Handle Animal","value":3},{"skill":"Stealth","value":12,"special":"+15 in native environment"},{"skill":"Survival","value":7}],"languages":["Common","Barbegazi"],"environments":["cold hills","cold mountains"],"organizations":["solitary","hunting party (2-5 and 1 winter wolf)","band (20-50 plus 50% noncombatants plus 1 3rd-level sergeant per 20 adults and 1 leader of 4th-6th level and 2-4 winter wolves)","clan (50-100 plus 50% noncombatants plus 1 3rd-level sergeant per 20 adults, 1-2 lieutenants of 4th-5th level, 1 leader of 6th-8th level, and 5-7 winter wolves)"],"treasure":"standard (short sword, 3 daggers)","description_visual":"This humanoid stands just over 3 ft. tall and has white hair, glossy white skin and deep blue eyes. Its beard is long and flowing and appears to be made of icicles. Its ft. are large and flat.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Snow Move","kind":"Ex","details":"Because of its oversized flat ft., a barbegazi can walk on top of deep snow and suffers no penalties when moving through snowy or icy terrain."}],"description":"Barbegazis are often referred to as snow or ice gnomes, a name they don't appreciate. They inhabit frigid hills and mountains where they spend their time engaging in activities they enjoy: hunting, fishing, and wrestling. Barbegazi homes are constructed of large blocks of ice and stone and are often built into the sides of hills and mountains or are in fact part of the mountain itself. Their homes are frequently targeted by white dragons (who consider their flesh a delicacy). A barbegazi prefers to avoid combat, using misdirection and deception (including well-placed traps and pitfalls) whenever possible to mislead and detour potential opponents. If a barbegazi knows an enemy is coming, it will most certainly have several traps and snares in place by the time the enemy arrives. If a barbegazi engages an opponent, it usually opens combat with its icicle blast before moving to attack with its short sword. A barbegazi isn't stupid and will not risk its life in battle (unless it is defending its clan). If forced to flee, a barbegazi burrows into the snow and attempts to escape. Barbegazis stand about 3 and a half ft. tall and weigh 45 pounds on average. Barbegazi Society A barbegazi clan is led by the eldest male. Females play a lesser role than males in barbegazi society, though many are as capable (or more) than many of the males in the clan. Young barbegazi are trained from a young age in the art of combat and survival. Aside from white dragons, barbegazis have tolerable relations with most cold-dwelling races and often initiate trade with frost giant clans. Typical goods traded by a barbegazi clan are furs and meat. They don't associate or particularly care for frost men (q.v.).","as_character":[{"description":"Barbegazi leaders tend to be rogues or clerics. Barbegazi generally worship Pharasma, and their clerics favor the ice subdomain and the death and knowledge domains.","racial_traits":[{"type":"Ability Score Bonuses","value":"+2 Dexterity, +2 Constitution, -2 Charisma. Low-light Vision."},{"type":"Racial Hit Dice","value":"A barbegazi begins with two levels of humanoid, which provide 2d8 Hit Dice, a base attack bonus of +1, and base saving throw bonuses of Fort +3, Ref +0, and Will +0."},{"type":"Racial Skills","value":"A barbegazi's humanoid levels give it skill points equal to 2 x (2 + Int modifier). Racial skills for barbegazi are Climb, Craft (any), Handle Animal, Heal, Profession, Ride, Stealth, and Survival. They receive a +3 racial bonus on Craft (trapmaking) and Survival checks, and a +3 racial bonus on Stealth checks that increases to +6 in their natural environment."},{"type":"Cold Subtype","value":"This gives barbezagi immunity to cold and vulnerability to fire."},{"type":"Racial Feats","value":"A barbegazi's humanoid levels give it one feat."},{"type":"AC","value":"+2 natural armor bonus."},{"type":"Speed","value":"Barbezagi have a base land speed and burrow speed of 20 ft. They can burrow through snow at normal burrow speed, or through solid ice at half speed."},{"type":"Spell-like Abilities","value":"See above. The save DCs are Charisma-based, and barbegazi receive a +2 racial bonus on the save DCs of their racial spell-like abilities."},{"type":"Special Qualities","value":"Snow move"},{"type":"Languages","value":"Barbegazis begin play speaking Common and Barbegazi. Barbegazi with high intelligence scores can choose from any of these bonus languages: Draconic, Dwarven, Giant, Gnome."}]}],"ecology":"","habitat_society":""},{"name":"Baric","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":13,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+1 Dex, +1 natural, +1 size","hp":14,"hd":"2d10+3","hdvalue":2,"fort":3,"ref":4,"will":1,"speed":[{"type":"land","speed":40}],"melee":"bite +3 (1d6) and 2 claws +3 (1d3)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":13,"constitution":11,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":2,"cmb":1,"cmd":12,"cmd_special":"+8 vs. trip","feats":[{"feat":"Toughness"}],"skills":[{"skill":"Perception","value":6},{"skill":"Stealth","value":5}],"environments":["any underground"],"organizations":["solitary","pack (2-8)"],"treasure":"none","description_visual":"This creature appears as a 6-legged rat with black fur and yellow eyes.  It has a long duck-like bill lined with rows of needle-sharp teeth.","source":"Tome of Horrors Complete (3pp)","description":"Barics are strange rat-like creatures that hunt in packs. The average baric is 3 ft. long and weighs 50 pounds, though they can grow to a length of 7 ft. and weigh about 150 pounds. Some races keep barics as pets, though more often than not, these unpredictable monsters turn on their masters within a short time of entering captivity.\n\nBarics hunt in small packs. When prey is encountered, they slowly circle it, moving in to attack with claws and bites. If more than half the pack is slain, the remaining barics usually flee, unless they are very hungry, in which case they all fight to the death.","ecology":"","habitat_society":"","credit":"The Baric originally appeared in the module B3 Palace of the Silver Princess (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Blood Hawk","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":14,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":6,"hd":"1d10+1","hdvalue":1,"fort":3,"ref":4,"will":2,"speed":[{"type":"land","speed":10},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"bite +4 (1d4), 2 talons +4 (1d3)","space":"5 ft.","reach":"5 ft.","strength":11,"dexterity":15,"constitution":12,"intelligence":2,"wisdom":14,"charisma":6,"baseatk":1,"cmb":1,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":4},{"skill":"Perception","value":6,"special":"+14 in daylight"}],"environments":["any forests","any hills","any mountains","any plains"],"organizations":["flock (6-11)"],"treasure":"incidental","description_visual":"This creature appears as a hawk with red talons and a dull red beak.","source":"Tome of Horrors Complete (3pp)","description":"The blood hawk is nearly identical to a normal hawk and is often mistaken for one, but a blood hawk is stronger and far more aggressive than a normal hawk. Blood hawks love the taste of human flesh and are relentless in their hunt of human prey. They often steal gems from the corpses of their humanoid prey, which they use to line their nests.\n\nBlood hawks are fierce combatants and quickly swoop down on their prey, attacking with their razor sharp talons and beak. Blood hawks fight to the death.","ecology":"","habitat_society":"","credit":"The Blood Hawk originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Brine Zombie","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"undead","subtypes":["aquatic"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":9,"ac_flat_footed":13,"ac_mods":"-1 Dex, +4 natural","hp":22,"hd":"4d8+4","hdvalue":4,"fort":1,"ref":0,"will":4,"dr":"5/slashing","immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"cutlass +5 (1d6+2/19-20) or slam +5 (1d6+3)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":8,"wisdom":10,"charisma":10,"baseatk":3,"cmb":5,"cmd":14,"feats":[{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Swim","value":10}],"sq":[{"type":"staggered"}],"environments":["any aquatic"],"organizations":["gang (2-4)","crew (6-11)"],"treasure":"none","description_visual":"This creature appears as a rotting humanoid dressed in tattered and ragged clothing. Its semi-bloated body glistens from the slimy mixture of water and seaweed that hangs from its form. The creature's rotting flesh is blue-green in color. No semblance of life burns in its eyes.","group":"Zombie","source":"Tome of Horrors Complete (3pp)","description":"Brine zombies are the remnants of a ship's crew that has perished at sea.\n\nThey are mindless creatures, not very pleasant to look at, and relentless in their attacks on the living. The spark of evil that brought them back from the ocean depths drives them to seek the living so they may join them in their watery graves. Brine zombies appear much as they did in life.\n\nBrine zombies attack an opponent with their cutlasses or fists in melee.\n\nIf a brine zombie successfully grabs an opponent, it dives overboard and attempts to drown the victim by pinning him underwater.","ecology":"","habitat_society":"","gear":"cutlass"},{"name":"Dire Corby","cr":1,"xp":400,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":14,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+1 Dex, +3 natural","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":4,"will":8,"speed":[{"type":"land","speed":30}],"melee":"2 claws +5 (1d4+3)","space":"5 ft.","reach":"5 ft.","strength":16,"dexterity":12,"constitution":13,"intelligence":6,"wisdom":10,"charisma":8,"baseatk":2,"cmb":26,"cmb_special":"+4 vs. grapple","cmd":36,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"}],"skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":8},{"skill":"Stealth","value":5}],"languages":["Aklo"],"environments":["any underground"],"organizations":["gang (2-5)","flock (6-11)","community (10-60 plus 1 leader of 3rd-5th level per 10 adults)"],"treasure":"standard","description_visual":"This creature resembles a wingless bipedal crow with slick black feathers, powerful arms that end in razor-sharp claws, and a gold beak.","source":"Tome of Horrors Complete (3pp)","description":"Dire corbies are humanoid, bipedal birdmen that dwell deep beneath the surface world. They make their homes in large, open caverns, hollowing out individual shelters in the walls themselves. These creatures don't possess wings now, but did in some remote part of their past. Why their wings disappeared and were replaced by claws is unknown. Dire corbies are omnivores but prefer a diet of fresh meat, enjoying the flesh of subterranean rodents, animals, and even other races. They are particularly fond of the flesh of bats, savoring the leathery grit of their flesh. Dire corbies hunt in flocks. They enjoy the thrill of the hunt and enjoy running their prey down, toying with it before swooping in and tearing it to shreds with their claws. Dire corbies always fight to the death and never flee, even when faced with overwhelming odds.","as_character":[{"description":"Dire corbies possess racial Hit Dice and may have class levels. Dire corbies have the following racial traits.","racial_traits":[{"type":"Ability Score Bonuses","value":"+6 Strength, +2 Dexterity, +2 Constitution, -4 Intellegence, -2 Charisma. Dire corbies are physically impressive, but lack judgment. Base speed A dire corby's base land speed is 30 ft. Darkvision Dire corbies can see in darkness out to 60 ft. Racial Hit Dice Dire corbies begin play with 2 levels of monstrous humanoid, which provides 2d10 HD, a base attack bonus of +2, and base saves of Fort +0, Ref +3, Will +3. Racial Skills A dire corby's monstrous humanoid levels give it skill points equal to 2 x (4 + Int modifier, minimum 1). Dire corbies receive a +4 racial bonus on Perception checks. Racial Feats A dire corby's monstrous humanoid levels gives it one feat. AC Dire corbies receive a +3 natural armor bonus Natural Weapons A dire corby may attack with 2 claws (1d4) Languages Dire corbies begin play speaking Aklo. Dire corbies with high intelligence may choose from the following bonus languages: Common, Undercommon, Goblin."}]}],"ecology":"","habitat_society":"","credit":"The Dire Corby originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Dire Shadow Rat","cr":1,"xp":400,"alignment":"N","size":"Small","type":"undead","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":16,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 Dex, +2 natural, +1 size","hp":7,"hd":"1d8+3","hdvalue":1,"fort":3,"ref":3,"will":8,"defensive_abilities":["incorporeal form","shadow blend"],"immunities":["undead traits"],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"bite +4 (1d4 plus 1d3 Strength damage plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"disease","details":"DC 13"}],"strength":10,"dexterity":17,"intelligence":2,"wisdom":12,"charisma":16,"baseatk":0,"cmb":25,"cmb_special":"+4 vs. grapple","cmd":37,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Finesse","type":"bonus"}],"skills":[{"skill":"Acrobatics","value":3,"special":"+7 jump"},{"skill":"Climb","value":8},{"skill":"Perception","value":8},{"skill":"Stealth","value":11}],"environments":["any underground"],"organizations":["solitary","pack (6-11)"],"treasure":"none","description_visual":"This creature appears as a rat with rotting flesh, torn and matted fur, and reddish blazing eyes. Its semi-translucent skin shows discolored bones and muscles.","group":"Rat","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Disease","kind":"Ex","details":"Filth fever: Bite-injury; save Fort DC 11; onset 1d3 days, frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves. The save DC is Charisma-based."},{"type":"Incorporeal Form","kind":"Su","details":"A shadow rat can, as a standard action, assume an incorporeal form for up to 1 hour per day. In this form, the shadow rat loses its natural AC bonus but gains a +2 deflection bonus to AC. While in this form, the shadow rat is AC 16 (+2 deflection, +2 Dex, +2 size), touch 15, flat-footed 13. The shadow rat can still attack corporeal opponents while in its incorporeal form, but its attack only inflicts Strength damage and cannot cause physical damage. The shadow rat gains the incorporeal subtype while using this ability."},{"type":"Shadow Blend","kind":"Ex","details":"A shadow rat can disappear into the shadows as a move action, gaining total concealment in all levels of illumination save bright light."},{"type":"Strength Damage","kind":"Su","details":"A shadow rat deals Strength damage to living foes it bites. A creature reduced to 0 Strength cannot move but doesn't die-at least, not until the shadow rat's physical damage takes its toll."}],"description":"Shadow rats are undead rats that can assume an incorporeal form. Other than their semi-translucent form (which they maintain regardless of their incorporeality or not), they resemble their earthly counterparts in all respects. Shadow rats attack relentlessly with their bite attack. Unlike normal shadows, shadow rats don't create spawn.","ecology":"","habitat_society":""},{"name":"Dragonfish","cr":1,"xp":400,"alignment":"N","size":"Small","type":"animal","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":16,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+2 Dex, +3 natural, +1 size","hp":9,"hd":"2d8","hdvalue":2,"fort":3,"ref":5,"will":8,"defensive_abilities":["camouflage","spines"],"speed":[{"type":"swim","speed":20}],"melee":"bite +2 (1d4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"}],"strength":10,"dexterity":15,"constitution":11,"intelligence":2,"wisdom":11,"charisma":4,"baseatk":1,"cmb":17,"cmd":29,"feats":[{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":7},{"skill":"Stealth","value":10},{"skill":"Swim","value":10}],"environments":["any aquatic"],"organizations":["solitary"],"treasure":"none","description_visual":"This small flat fish has brown scales mottled with black. A series of needle-like spines runs the length of the fish on its dorsal side.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Spines","kind":"Ex","details":"A creature that steps on a dragonfish or strikes it with an unarmed strike or a natural weapon takes 1d4 points of piercing damage from the fish's dorsal barbs and is subjected to its poison. Melee weapons don't endanger a user in this way. A charging or running creature must immediately stop if it steps on a dragonfish. A creature that takes more than 2 points of damage from a dragonfish's barb has its speed is reduced by half because its foot is wounded. This movement penalty lasts until the barb is removed, requiring a DC 15 Heal check at least 1 point of magical healing. A failure on the Heal check to remove a dragonfish spine results in 1d4 additional points of damage."},{"type":"Dragonfish Poison","kind":"Ex","details":"Spine-injury; save Fort DC 11; frequency 1/round for 6 rounds; effect 1d2 Constitution; cure 1 save"},{"type":"Camouflage","kind":"Ex","details":"It takes a successful DC 20 Perception check to recognize a motionless dragonfish for what it really is."}],"description":"A dragonfish is a small, 2-foot long, flat fish that makes its home on the bottom of shallow lakes, rivers, or streams. The dragonfish's back is covered with long, sharp spines. A dragonfish's dorsal spines carry a virulent poison that is delivered whenever an opponent contacts a spine. They are non-aggressive and spend their days eating miniscule water creatures, insects, and aquatic plants.\n\nDragonfish are not aggressive and prefer to lie on the bottom of a body of water, waiting for a victim to step on it so its poisonous spines penetrate the victim's flesh. If forced into melee, a dragonfish attacks with its bite.","ecology":"","habitat_society":"","credit":"The Dragonfish originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Edon","cr":1,"xp":400,"alignment":"N","size":"Small","type":"magical beast","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["stench (DC 13, 1d4 rounds)"],"ac":14,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 Dex, +1 natural, +1 size","hp":15,"hd":"2d10+4","hdvalue":2,"fort":5,"ref":5,"will":1,"immunities":["sonic"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"speed_mod":"brachiate","melee":"2 claws +5 (1d3+1), bite +5 (1d4+1)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"constitution":14,"intelligence":4,"wisdom":12,"charisma":8,"baseatk":2,"cmb":2,"cmd":14,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":13},{"skill":"Perception","value":5}],"languages":["Sylvan (can't speak)"],"sq":[{"type":"deaf"}],"environments":["temperate forests","warm forests"],"organizations":["gang (2-5)","pack (6-11)"],"treasure":"standard","description_visual":"This creature resembles a small hairy ape-like humanoid with long muscular arms that end in slightly oversized clawed hands.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Brachiate","kind":"Ex","details":"An edon can move its climb speed through treetops by leaping from tree to tree so long as the trees are no more than 10 ft. apart and the creature's hands are empty."},{"type":"Deaf","kind":"Ex","details":"An edon is deaf and automatically fails any Perception check based on sound. It is immune to any effect that requires the target be able to hear."},{"type":"Stench Aura","kind":"Ex","details":"An edon's stench aura affects only humans and halflings, and creatures with the scent special ability. All other creatures are immune to its effects. An edon can suppress its stench for 1d2 hours by rubbing juniper berries on its body. Doing so negates the aura for the duration."}],"description":"Edons are forest-dwelling creatures with a great fondness for human and halfling flesh. At first glance they appear to be monkeys or small apes with powerful arms and sharp claws. They are territorial creatures that dine on mosses, leaves, small forest animals, and of course their favorite meal: humans and halflings. Edons are active during the day and rest in their treetop lairs at night.\n\nAn edon stands about 3 ft. tall and weighs around 60 pounds. Its fur is brown or brownish-gray and its eyes are gray. An edon has a lifespan of roughly 50 years.\n\nEdons are completely deaf and don't speak, though they do seem to understand the Sylvan tongue. They communicate with others of their kind through body motion and sign language.\n\nEdons attack by hiding among the treetops and dropping on unsuspecting prey. They are relentless in their attacks, slashing and biting their foe until it is dead. Edons realize they are not the strongest or largest creatures, so they rely on their sheer numbers to gang up on their foes. Recent encounters with packs of edons have led to stories of pack leaders who appear to be smarter than the average edon and who employ traps such as tripwires and deadfalls to catch or disable their prey.","ecology":"","habitat_society":""},{"name":"Fire Fish","cr":1,"xp":400,"alignment":"N","size":"Small","type":"animal","subtypes":["aquatic","fire"],"init":6,"senses":[{"type":"low-light vision"},{"type":"tremorsense","modifier":"10 ft."}],"auras":["heat (5 ft. radius)"],"ac":14,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+1 Dex, +2 natural, +1 size","hp":13,"hd":"3d8","hdvalue":3,"fort":3,"ref":5,"will":2,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"swim","speed":40}],"melee":"slam -1 (1d4-4 plus heat)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"heat","details":"1d4 fire damage"}],"strength":3,"dexterity":14,"constitution":10,"intelligence":1,"wisdom":12,"charisma":5,"baseatk":2,"cmb":0,"cmd":12,"feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Perception","value":7},{"skill":"Sense Motive","value":3},{"skill":"Swim","value":16}],"environments":["any (Plane of Fire)"],"organizations":["solitary","school (4-80)"],"treasure":"none","description_visual":"Light orange to bright red in color, the fire fish is approximately the size of a common salmon. Firefish frequently stay in their schools; a solitary fish is easy prey for many predators.  Firefish spawn yearly, and attempt to return to their place of origin to do so. If unable, a firefish locates a warm, rocky area to deposit their eggs. The females perish within a day after depositing the eggs. The males, after fertilizing the eggs, swim off, living perhaps another week before perishing.  These are just a few of the possible creatures available, but they should be a good starting point to create other elemental animals.","group":"Animal Elemental","source":"Tome of Horrors 4 (3pp)","description":"Aquatic Firefish can swim and breathe in molten lava as easily as a regular fish in water. They are 'aquatic' only in the sense that their natural environment is lava instead of water.","ecology":"","habitat_society":"","credit":"Originally appearing in Rappan Athuk Reloaded (© Necromancer Games, 2006)"},{"name":"Fire Snake","cr":1,"xp":400,"alignment":"N","size":"Small","type":"outsider","subtypes":["extraplanar","fire"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+3 Dex, +3 natural, +1 size","hp":13,"hd":"2d10+2","hdvalue":2,"fort":1,"ref":6,"will":4,"immunities":["fire"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"bite +6 (1d4 plus paralysis)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"paralysis","details":"DC 12, 1d6 rounds"}],"strength":10,"dexterity":17,"constitution":12,"intelligence":1,"wisdom":12,"charisma":7,"baseatk":2,"cmb":1,"cmd":14,"cmd_special":"can't be tripped","feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Climb","value":11},{"skill":"Perception","value":9},{"skill":"Stealth","value":15}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pack (2-5)"],"treasure":"half standard","description_visual":"This creature looks like a snake with reddish-orange scales and stark white eyes without pupils.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Paralysis","kind":"Ex","details":"A fire snake's fangs inject an anesthetizing venom. A target hit by a fire snake's bite attack must succeed on a DC 12 Fortitude save or be paralyzed for 1d6 rounds. The save DC is Constitution-based."}],"description":"A fire snake resembles a normal snake and ranges in size from 2 ft. to 6 ft. in length. Fire snakes make their homes in fires and rarely journey more than 30 ft. from such an open flame. Sages conjecture that fire snakes are some form of larval salamander from the Plane of Fire.\n\nA fire snake's preferred method of attack is to hide in a nearby fire and then surprise its foes as they come nearby. A fire snake attacks by biting its opponents with its sharp fangs.","ecology":"","habitat_society":"","credit":"The Fire Snake originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Flumph","cr":1,"xp":400,"alignment":"LG","size":"Small","type":"aberration","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+3 Dex, +4 natural, +1 size","hp":9,"hd":"2d8","hdvalue":2,"fort":0,"ref":3,"will":5,"resists":[{"type":"acid","value":10}],"speed":[{"type":"land","speed":5},{"type":"fly","speed":20,"maneuverability":"perfect"}],"melee":"sting +5 (1d4 plus acid injection)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"acid injection"},{"type":"stench spray","details":"DC 11, 1d6 rounds, every 1d4 rounds"}],"strength":10,"dexterity":16,"constitution":11,"intelligence":10,"wisdom":14,"charisma":10,"baseatk":1,"cmb":0,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Diplomacy","value":2},{"skill":"Fly","value":18},{"skill":"Perception","value":7},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":11}],"environments":["any land","any underground"],"organizations":["solitary","pair","colony (4-16)"],"treasure":"standard (including body, worth 200 gp in rare component elements)","description_visual":"This small strange creature looks like a saucer-shaped jellyfish with many small spike-like tentacles dangling from its underbelly. Its body is milky-white in color. Two short eyestalks protrude from the top of its body. Its eyestalks are gray as are its tentacles. Its eyes are jet black.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid Injection","kind":"Ex","details":"When a flumph strikes an opponent with its spikes, it injects a burning, irritating acid that deals 1d4 points of damage immediately and another 1d4 points on the round after the attack. The target can end the acid's effects by submerging the wound in water for a round or by being treated with a DC 15 Heal check. A creature grappling or swallowing the flumph takes this acid damage automatically every round it maintains this contact."},{"type":"Stench Spray","kind":"Ex","details":"A flumph can spray a 20-foot line of foul-smelling liquid once every 1d4 rounds. This spray functions like the stench universal monster ability, except it only affects creatures struck by the spray, which must make a DC 11 Fortitude save or be sickened for 5 rounds. The save DC is Constitution-based. Alternatively, the flumph can concentrate the spray on a single target within 5 ft. - if the target fails its saving throw, it is nauseated for 5 rounds; otherwise, it is sickened for 1 minute. The odor from this spray lingers in the area and on all creatures struck for 1d4 hours, and can be detected at a range of 100 ft. (creatures with the scent ability can smell it at double this range)."}],"description":"Flumphs are small, very strange creatures that spend their days floating along looking for food and water. They are non-offensive and only attack when actively hunting for food. Flumphs prefer the darkness of the underground and are rarely, if ever, encountered above ground. The average flumph is about 2 ft. in diameter.\n\nThe flumph spends most of its time hunting small animals and vermin, which it kills and devours by dropping on them and piercing them with its acidic spikes. If threatened by a creature larger than itself, it fires its nauseating spray in an attempt to repel its attackers. If this attack fails, the flumph rises above its foes and drops at them, attacking with its spikes.","ecology":"","habitat_society":"","credit":"The Flumph originally appeared in the First Edition Fiend Folio (© TSR/Wizards of the Coast, 1981) and is used by permission."},{"name":"Frost Dwarf","cr":1,"xp":400,"alignment":"CN","size":"Medium","type":"humanoid","subtypes":["cold","dwarf"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":13,"ac_touch":10,"ac_flat_footed":13,"ac_mods":"+2 armor, +1 natural","hp":13,"hd":"2d8+4","hdvalue":2,"fort":5,"ref":0,"will":1,"immunities":["cold"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":20}],"melee":"battleaxe +3 (1d8+1 plus 1d4 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-ft. line, 2d6 cold damage; DC 13 Ref half, 3/day"}],"strength":13,"dexterity":10,"constitution":14,"intelligence":11,"wisdom":13,"charisma":6,"baseatk":1,"cmb":2,"cmd":12,"feats":[{"feat":"Weapon Focus (battleaxe)"}],"skills":[{"skill":"Craft (any)","value":5},{"skill":"Perception","value":1},{"skill":"Stealth","value":0,"special":"+4 in snow"},{"skill":"Survival","value":6}],"languages":["Common","Dwarf","Giant"],"sq":[{"type":"dwarf traits"}],"environments":["cold mountains"],"organizations":["Team (2-4)","squad (9-16 plus 3 3rd-level sergeants and 1 leader of 3rd-8th level","clan (30-100 plus 30% non-combatants plus 1 3rd level sergeant per 10 adults","5 5th-level lieutenants","3 7th level captains","jarldom (2-6 clans plus one jarl","king of level 10+)"],"treasure":"standard (leather, battleaxe)","description_visual":"This stocky humanoid is about 4 ft. tall with bright blue eyes and long bluish-white hair.","group":"Dwarf","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Cold","kind":"Su","details":"When a frost dwarf is in a cold climate, it deals an extra 1d4 points of cold damage with both weapons and natural attacks. This doesn't function if the frost dwarf is in temperate or warmer climates."}],"description":"Frost dwarves are chaotic and untamed as the glacial expanses which they inhabit. Often they have lairs hidden deep beneath snow and ice packs burrowed deep into the living stone where they plunder for gemstones and metals as any other dwarf. Skilled crafters, frost dwarves trade freely with frost giants, constructing many of their massive weapons and armor in exchange for loot and protection. They are typically disliked and dismissed by their \"true\" dwarven kin who consider them to be abominations or worse.\n\nFrost dwarves are known for their rudeness and coarse sense of humor. They are however famed for their skill at craftsmanship and the enchantment of strange and unusual magical items. Most typically frost dwarves are worshippers of Thrym and enjoy his taste in puzzles and conundrums. Frost dwarf traps are legendary amongst the frozen wastes of the world.\n\nFrost dwarves are proficient combatants and make use of their natural surroundings to their advantage. They assault enemies with crossbows from distance and use their battleaxe to crush charges. They enjoy surprise and prefer to attack using dirty tricks such as unleashing avalanches upon unsuspecting travelers, then pick through their frozen carcasses for loot. Higher level frost dwarves often ride winter wolves as mounts. It isn't uncommon for 1-2 of the beasts to be in the company of a frost dwarf squad.\n\nFrost Dwarf Society\n\nFrost dwarves are commonly found serving frost giant masters. In their own nations they elect a king from the ruling clans. This jarl rules for life though doesn't necessarily establish any form of dynasty. Frost dwarf clans organize themselves loosely after the fashion of their mountain and hill dwarf cousins, but are more tribal in nature. Frost dwarves keep a semblance of military titles amongst the various clans. Frost dwarves are attuned to the use of magic and many of their leaders are powerful wizards or clerics. They are equally likely to be barbarians.\n\nThere are no frost dwarf females. Frost dwarves are born to the union of a frost dwarf and dwarf (any), human, gnome, or frost or hill giant. Any child conceived from such a union is always born a frost dwarf male and reaches full size within a matter of weeks.\n\nFrost dwarf children are often abandoned near known frost dwarf communities where it is expected they will be found and cared for or claimed by their father's clan. Frost dwarves are often shunned by their maternal parent as an abomination, especially among hill and mountain dwarves who likely banish the mother from their halls if she survives the child's birth. The exception to this rule is that of frost dwarves born to frost giant and jotun mothers. In frost giant culture, frost dwarves are considered a sign of good luck. They are however still sent to live amongst others of their kind until they reach the age of maturity, which is about 50 years old, when they are welcomed back amongst the frost giants who sired them.","ecology":"","habitat_society":""},{"name":"Ghoul Monkey","cr":1,"xp":400,"alignment":"CE","size":"Small","type":"undead","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":13,"hd":"2d8+4","hdvalue":2,"fort":2,"ref":2,"will":5,"immunities":["undead traits"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +4 (1d2+1 plus disease) and 2 claws +4 (1d2+1 plus disease)","space":"5 ft.","reach":"5 ft.","strength":12,"dexterity":15,"intelligence":10,"wisdom":14,"charisma":14,"baseatk":1,"cmb":1,"cmd":13,"feats":[{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":4},{"skill":"Climb","value":14},{"skill":"Perception","value":7},{"skill":"Stealth","value":11}],"environments":["warm jungles"],"organizations":["solitary","pair","pack (4-12)"],"treasure":"none","description_visual":"Filthy, emaciated beasts, ghoul monkeys are depraved examples of harmless animals saturated in evil.","group":"Monkey","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Disease","kind":"Su","details":"Ghoul Monkey Fever: Bite-injury; save DC 13 Fort; onset 1 day; frequency 1/day; effect 1d2 Con and 1d2 Dex damage; cure 2 consecutive saves. The save DC is Charisma-based."}],"description":"Ghoul monkeys are cunning, undead monkeys 2-3 ft. tall, weighing 10-20 pounds. These monkeys often appear in jungle areas where there is great residue of evil and chaos, such as forgotten temples or altars where dead monkeys might rise in this vile form of undeath. Unlike \"human-type\" ghouls, their bite doesn't cause paralysis.\n\nThey extremely vulnerable to holy water (2d6 damage) and to being turned (no channel resistance).\n\nGhoul monkeys lose the social drive of normal monkeys, but occasionally group together when the draw of evil is powerful enough.","ecology":"","habitat_society":"","credit":"Original author Scott Casper  Originally appearing in Jungle Ruins of Madaro-Shanti (© Frog God Games, 2010)"}];
